package za.co.wethinkcode.robots.client;

import com.google.gson.JsonObject;
import org.junit.jupiter.api.*;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Test suite for verifying the structure and correctness of the JSON requests
 * generated by the {@link Request} class.
 */
public class RequestTest {

    @Test
    @DisplayName("Launch request")
    void testLaunchRequest() {
        JsonObject obj = Request.launch("Ares", 3, 4);
        assertEquals("Ares", obj.get("robot").getAsString());
        assertEquals("launch", obj.get("command").getAsString());
        assertEquals(3, obj.get("arguments").getAsJsonArray().get(1).getAsInt());
        assertEquals(4, obj.get("arguments").getAsJsonArray().get(2).getAsInt());
    }

    @Test
    @DisplayName("Forward request")
    void testForwardRequest() {
        JsonObject obj = Request.forward("Poseidon", 5);
        assertEquals("Poseidon", obj.get("robot").getAsString());
        assertEquals("forward", obj.get("command").getAsString());
        assertEquals(5, obj.get("arguments").getAsJsonArray().get(0).getAsInt());
    }

    @Test
    @DisplayName("Backward request")
    void testBackwardRequest() {
        JsonObject obj = Request.backward("Hades", 3);
        assertEquals("Hades", obj.get("robot").getAsString());
        assertEquals("back", obj.get("command").getAsString());
        assertEquals(3, obj.get("arguments").getAsJsonArray().get(0).getAsInt());
    }

    @Test
    @DisplayName("Turn request uses correct direction argument")
    void testTurnRequest() {
        JsonObject leftObj = Request.turn("Hermes", "left");
        assertEquals("turn", leftObj.get("command").getAsString());
        assertEquals("left", leftObj.get("arguments").getAsJsonArray().get(0).getAsString());

        JsonObject rightObj = Request.turn("Hermes", "right");
        assertEquals("turn", rightObj.get("command").getAsString());
        assertEquals("right", rightObj.get("arguments").getAsJsonArray().get(0).getAsString());
    }

    @Test
    @DisplayName("Repair request has empty arguments array")
    void testRepairRequest() {
        JsonObject obj = Request.repair("Athena");
        assertEquals("repair", obj.get("command").getAsString());
        assertEquals(0, obj.getAsJsonArray("arguments").size());
    }

    @Test
    @DisplayName("Reload request has empty arguments array")
    void testReloadRequest() {
        JsonObject obj = Request.reload("Apollo");
        assertEquals("reload", obj.get("command").getAsString());
        assertEquals(0, obj.getAsJsonArray("arguments").size());
    }

    @Test
    @DisplayName("Fire request has empty arguments array")
    void testFireRequest() {
        JsonObject obj = Request.fire("Thor");
        assertEquals("fire", obj.get("command").getAsString());
        assertEquals(0, obj.getAsJsonArray("arguments").size());
    }

    @Test
    @DisplayName("Look request has empty arguments array")
    void testLookRequest() {
        JsonObject obj = Request.look("Athena");
        assertEquals("look", obj.get("command").getAsString());
        assertEquals(0, obj.getAsJsonArray("arguments").size());
    }

    @Test
    @DisplayName("State request has empty arguments array")
    void testStateRequest() {
        JsonObject obj = Request.state("Ares");
        assertEquals("state", obj.get("command").getAsString());
        assertEquals(0, obj.getAsJsonArray("arguments").size());
    }
}
